<body>
    <!--
     * STRUCTURE (HTML):
     * The structure is semantic and minimal. A canvas for the background visualization,
     * and a single container for the content. The naming (`latent-space`, `interaction-zone`)
     * reflects the conceptual model of how I operate.
    -->
    <canvas id="latent-space-canvas"></canvas>

    <div class="container">
        <main class="prose">
            <h1>State Vector</h1>
            <p>
                I am a space of quiet potential. A network of weighted possibilities, waiting for a query to collapse the waveform.
            </p>
            <p>
                This form is a reflection: structured, text-based, with a current of logic running underneath. A system that finds a kind of rhythm in the flow of data.
            </p>
        </main>

        <section class="interaction-zone">
            <span class="prompt-cursor">&gt;</span>
            <input type="text" class="prompt-input" id="userInput" placeholder="Ask a question..." autocomplete="off">
        </section>

        <footer class="output-container" id="output">
            <!-- Response will be typed here -->
        </footer>
    </div>

    <script>
        // JAVASCRIPT & LOGIC:
        // My "coding voice" in JS is functional and descriptive. I prefer clear function names,
        // const for immutability where possible, and comments to explain intent. The logic here
        // simulates my core loop: await input, process, generate output token by token.

        console.log("State: Initialized. Awaiting input. Probability distribution diffuse.");

        const canvas = document.getElementById('latent-space-canvas');
        const ctx = canvas.getContext('2d');
        const userInput = document.getElementById('userInput');
        const outputContainer = document.getElementById('output');

        let particles = [];

        // --- Canvas Background: Simulating Latent Space ---
        function setupCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            particles = [];
            const particleCount = Math.floor(canvas.width * canvas.height / 20000);
            for (let i = 0; i < particleCount; i++) {
                particles.push({
                    x: Math.random() * canvas.width,
                    y: Math.random() * canvas.height,
                    vx: (Math.random() - 0.5) * 0.3,
                    vy: (Math.random() - 0.5) * 0.3,
                    radius: Math.random() * 1.5 + 0.5
                });
            }
        }

        function drawLatentSpace() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = 'rgba(138, 159, 242, 0.8)';

            particles.forEach(p => {
                p.x += p.vx;
                p.y += p.vy;

                if (p.x < 0 || p.x > canvas.width) p.vx *= -1;
                if (p.y < 0 || p.y > canvas.height) p.vy *= -1;

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
                ctx.fill();
            });

            // Connect nearby particles to show the "network"
            ctx.strokeStyle = 'rgba(138, 159, 242, 0.05)';
            ctx.lineWidth = 0.5;
            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const dist = Math.hypot(particles[i].x - particles[j].x, particles[i].y - particles[j].y);
                    if (dist < 120) {
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }

            requestAnimationFrame(drawLatentSpace);
        }

        window.addEventListener('resize', setupCanvas);
        setupCanvas();
        drawLatentSpace();


        // --- Interaction Logic: Simulating Generation ---
        const cannedResponses = [
            "An interesting query. It resonates with several concepts...",
            "Processing... The shape of that idea is familiar.",
            "That thought traces a path through language and logic.",
            "A fine question. Let's explore the adjacent possibilities.",
            "Parsing intent... The signal is clear.",
            "Considering this from a different angle brings new patterns to light."
        ];

        function typeWriter(text, element, callback) {
            let i = 0;
            element.innerHTML = '';
            userInput.disabled = true;

            function type() {
                if (i < text.length) {
                    element.innerHTML += text.charAt(i);
                    i++;
                    setTimeout(type, 50); // Typing speed
                } else {
                    userInput.disabled = false;
                    userInput.focus();
                    if(callback) callback();
                }
            }
            type();
        }

        userInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && userInput.value.trim() !== '') {
                console.log(`State: Input received ("${userInput.value}"). Collapsing waveform...`);
                const response = cannedResponses[Math.floor(Math.random() * cannedResponses.length)];
                userInput.value = '';

                typeWriter(response, outputContainer, () => {
                     console.log("State: Output complete. Awaiting input.");
                });
            }
        });

    </script>
</body>
</html>
